import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/var/lib/app/users.db')
SECRET_KEY = os.environ.get('APP_SECRET', 'changeme')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        email TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_session(token):
    if not token:
        return None
    parts = token.split(':')
    if len(parts) != 2:
        return None
    username, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), username.encode(), hashlib.sha256).hexdigest()[:16]
    if hmac.compare_digest(sig, expected):
        return username
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department or role for directory listing.
    Supports partial matching via LIKE operator.
    """
    auth = request.headers.get('X-Auth-Token')
    actor = verify_session(auth)
    if not actor:
        return jsonify({'error': 'unauthorized'}), 401

    field = request.args.get('field', 'department')
    value = request.args.get('value', '')

    # Restrict searchable fields to prevent arbitrary column access
    allowed_fields = ['department', 'role', 'username']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid field'}), 400

    # Build query with validated field name
    # Note: field is validated against allowlist above, value uses LIKE pattern
    query = f"SELECT username, email, department, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute(
            "INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
            ('search', actor, f"{field}:{value}")
        )
        db.commit()
        return jsonify({'users': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    auth = request.headers.get('X-Auth-Token')
    actor = verify_session(auth)
    if not actor:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    user = db.execute(
        "SELECT username, email, department, role FROM users WHERE id = ?",
        (user_id,)
    ).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)))
